const siteHeader=document.querySelector('.site-header');const onScroll=()=>siteHeader&&siteHeader.classList.toggle('scrolled',window.scrollY>8);onScroll();window.addEventListener('scroll',onScroll,{passive:true});
const menu=document.querySelector('.menu'),nav=document.querySelector('.links');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Zamknij menu':'Otwórz menu');menu.textContent=open?'Zamknij':'Menu';});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Otwórz menu')}));
document.querySelectorAll('.youtube-cover').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.video;if(!/^[A-Za-z0-9_-]{11}$/.test(id))return;const iframe=document.createElement('iframe');iframe.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1';iframe.title='Film 8699.pl';iframe.allow='autoplay; encrypted-media; picture-in-picture';iframe.allowFullscreen=true;button.replaceWith(iframe);}));
const track=document.querySelector('.brand-track'),windowEl=document.querySelector('.brand-window');function shiftBrands(direction){if(!track||!windowEl)return;track.style.animation='none';track.style.transform='none';track.classList.add('paused');windowEl.scrollBy({left:direction*300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}document.querySelector('.brands-prev')?.addEventListener('click',()=>shiftBrands(-1));document.querySelector('.brands-next')?.addEventListener('click',()=>shiftBrands(1));
document.querySelectorAll('[data-local-video]').forEach(button=>button.addEventListener('click',()=>{const video=document.createElement('video');video.src=button.dataset.localVideo;if(button.dataset.poster)video.poster=button.dataset.poster;video.controls=true;video.autoplay=true;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label',button.dataset.title||'Film 8699.pl');button.replaceWith(video);}));
document.querySelectorAll('[data-contact]').forEach(f=>f.addEventListener('submit',async e=>{e.preventDefault();const status=f.querySelector('.form-status'),button=f.querySelector('button[type=submit]');status.classList.add('visible');if(document.querySelector('meta[name=robots]').content.includes('noindex')){status.textContent='Zadzwoń do biura: Kościerzyna 58 680 87 12, Bytów 59 822 88 76.';return;}button.disabled=true;status.textContent='Wysyłanie…';try{const res=await fetch('/.netlify/functions/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const data=await res.json();if(!res.ok)throw new Error(data.message||'Nie udało się wysłać wiadomości.');status.textContent='Dziękujemy. Zapytanie zostało wysłane do wybranego biura.';f.reset();}catch(error){status.textContent=error.message+' W razie potrzeby skontaktuj się telefonicznie.';}finally{button.disabled=false;}}));const siteBase=document.documentElement.dataset.siteBase||'';const withBase=p=>p.startsWith('/')?siteBase+p:p;if(location.pathname===withBase('/oferta/')&&location.hash){const routes={firm:'ubezpieczenia-firm',komunikacyjne:'ubezpieczenia-komunikacyjne',domy:'ubezpieczenia-domu-i-mieszkania',zdrowie:'ubezpieczenia-na-zycie-i-zdrowie',sport:'ubezpieczenia-podrozy-i-sportu'};const route=routes[location.hash.slice(1)];if(route)location.replace(withBase('/'+route+'/'));}(function(){const root=document.querySelector('[data-hero-slider]');if(!root)return;const slides=[...root.querySelectorAll('.hero-slide')],countEl=root.querySelector('.hero-slider-count'),prev=root.querySelector('.hero-slider-prev'),next=root.querySelector('.hero-slider-next');if(!slides.length)return;let index=slides.findIndex(s=>s.classList.contains('is-active'));if(index<0)index=0;const label=n=>String(n).padStart(2,'0');const sync=()=>{countEl.textContent=label(index+1)+' / '+label(slides.length);};const show=nextIndex=>{if(nextIndex===index||!slides[nextIndex])return;slides[index].classList.remove('is-active');slides[index].setAttribute('aria-hidden','true');index=nextIndex;slides[index].classList.add('is-active');slides[index].removeAttribute('aria-hidden');sync();};const step=delta=>show((index+delta+slides.length)%slides.length);prev?.addEventListener('click',()=>step(-1));next?.addEventListener('click',()=>step(1));root.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();step(-1);}else if(e.key==='ArrowRight'){e.preventDefault();step(1);}});let touchX=null;root.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;},{passive:true});root.addEventListener('touchend',e=>{if(touchX==null)return;const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>48)step(dx<0?1:-1);touchX=null;},{passive:true});sync();})();